 "content": "from collections import deque


def transform(grid):
    """Remove the 3/9 object containing the fewest 9 markers."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            nines = 0
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                nines += grid[y][x] == 9
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and not seen[yy][xx]:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            components.append((nines, cells))
    if not components:
        return [row[:] for row in grid]
    _, cells = min(components, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for r, c in cells:
        out[r][c] = 0
    return out
